# Local-Claw AST toolkit — two roles: (A) RepoMapper context manager, (B) ASTEditor structural editor
# Layer 1 parsing: py-tree-sitter + tree-sitter-language-pack (cached, incremental)
# Layer 2 symbol map: tag queries -> networkx DiGraph -> personalized PageRank -> token-budgeted JSONL
# Layer 3 edit: ast-grep (polyglot rewrite) + ts-morph (type-aware TS refactor)

import json, os
from dataclasses import dataclass
import networkx as nx
from tree_sitter_language_pack import get_language, get_parser

@dataclass
class Tag:
    name: str; kind: str          # 'def' | 'ref', and symbol kind
    signature: str; parent: str
    file: str; line: int

class RepoMapper:
    """Role A: ranked repo map for the Gemma brain."""
    def __init__(self):
        self.cache = {}           # path -> {'mtime': float, 'tree': Tree, 'tags': list[Tag]}

    def _parse(self, path, lang):
        mtime = os.path.getmtime(path)
        ent = self.cache.get(path)
        if ent and ent['mtime'] == mtime:
            return ent['tags']    # incremental cache hit
        parser = get_parser(lang)
        src = open(path, 'rb').read()
        tree = parser.parse(src)  # error-tolerant: returns tree even on broken code
        tags = self._run_tag_query(lang, tree, src, path)
        self.cache[path] = {'mtime': mtime, 'tree': tree, 'tags': tags}
        return tags

    def _run_tag_query(self, lang, tree, src, path):
        # tags.scm shipped per grammar; matches() returns (pattern_idx, {capture: [nodes]})
        language = get_language(lang)
        query = language.query(open(f'queries/{lang}-tags.scm').read())
        out = []
        for _, caps in query.matches(tree.root_node):
            for cap_name, nodes in caps.items():        # e.g. 'name.definition.function'
                for n in nodes:
                    kind = 'def' if 'definition' in cap_name else 'ref'
                    out.append(Tag(n.text.decode(), kind, _sig(n), _parent(n),
                                   path, n.start_point[0] + 1))
        return out

    def get_repo_map(self, chat_files, max_tokens):
        g = nx.DiGraph()
        defs, refs = {}, []
        for path, lang in self._iter_repo():
            for t in self._parse(path, lang):
                (defs.setdefault(t.name, []).append(t) if t.kind == 'def'
                 else refs.append(t))
        for r in refs:                                  # edge: referencer -> definer
            for d in defs.get(r.name, []):
                g.add_edge(r.file, d.file, weight=g.get_edge_data(r.file, d.file, {}).get('weight', 0) + 1)
        personalization = {f: (50.0 if f in chat_files else 1.0) for f in g.nodes}
        ranks = nx.pagerank(g, personalization=personalization) if g else {}
        ranked = sorted((t for ts in defs.values() for t in ts),
                        key=lambda t: ranks.get(t.file, 0), reverse=True)
        lines, budget = [], max_tokens
        for t in ranked:                                # token-budget filter
            rec = json.dumps({'name': t.name, 'kind': t.kind, 'signature': t.signature,
                              'parent': t.parent, 'loc': f'{t.file}:{t.line}'})
            cost = len(rec) // 4
            if budget - cost < 0: break
            budget -= cost; lines.append(rec)
        return '\n'.join(lines)                          # JSONL

class ASTEditor:
    """Role B: structural editor."""
    def edit_file(self, path, pattern, replacement, lang):
        # ast-grep: AST-level rewrite (never regex); preview then apply
        import subprocess
        return subprocess.run(['ast-grep', 'run', '-p', pattern, '-r', replacement,
                               '--lang', lang, path], capture_output=True, text=True)

    def rename_ts_symbol(self, tsconfig_abspath, file, symbol, new_name):
        # delegate to a Node ts-morph script for TYPE-AWARE cross-file rename
        import subprocess
        return subprocess.run(['node', 'tools/ts_rename.mjs', tsconfig_abspath,
                               file, symbol, new_name], capture_output=True, text=True)

# tools/ts_rename.mjs (type-aware rename — tree-sitter cannot do this):
#   import { Project } from 'ts-morph';
#   const [tsconfig, file, sym, newName] = process.argv.slice(2);
#   const p = new Project({ tsConfigFilePath: tsconfig });   // MUST be absolute
#   const decl = p.getSourceFileOrThrow(file).getFunctionOrThrow(sym);
#   decl.rename(newName);                                    // updates all refs + imports
#   await p.save();                                          // in-memory until save()

# Tool-selection rule the harness encodes:
#   raw parsing / symbol map / chunking            -> tree-sitter (always-on, error-tolerant)
#   fast polyglot structural search & rewrite      -> ast-grep
#   type-aware TS/JS rename / move / find-refs     -> ts-morph
#   security taint / dataflow                      -> semgrep
